# -*- coding: utf-8 -*-
from pathlib import Path
import re,json,shutil,html
ROOT=Path('.'); OUT=Path('output'); SOURCES=OUT/'sources';SOURCES.mkdir(exist_ok=True)
used='P01 P02 P03 P04 P05 P08 P14 P15 P16 P17 P18 P21 M01 M02 M03 M04 M06 M07 M09 M14 M15 M16 M17 M18 M19 M20 M24'.split()
manifest=json.loads(Path('materials/manifest.json').read_text())
papers={x['id']:x for x in manifest['papers']}
source={}
for id in used:
 p=papers[id];txt=Path('materials')/p['text'];pdf=Path('materials')/p['pdf']
 for f in [txt,pdf]:shutil.copy2(f,SOURCES/f.name)
 chunks=re.split(r'\[PDF page (\d+)\]',txt.read_text())
 source[id]={'title':p['title'],'kind':'paper','file':pdf.name,'textfile':txt.name,'pages':{chunks[i]:chunks[i+1].strip() for i in range(1,len(chunks),2)},'sha256':p['pdfSha256']}
for f in sorted(Path('materials/novel').glob('N[0-9][0-9][0-9].txt')):
 shutil.copy2(f,SOURCES/f.name); lines=f.read_text().splitlines();paras={}
 for l in lines:
  m=re.match(r'\[(N\d+)-P(\d+)\]\s*(.*)',l)
  if m:paras[m[2]]=m[3]
 source[f.stem]={'title':lines[0].split('] ',1)[-1],'kind':'novel','file':f.name,'pages':paras}
