citations=[]
def p(id,page,loc):
 citations.append((id,str(page),loc));return f'<button class="cite" data-source="{id}" data-page="{page}" data-loc="{html.escape(loc,quote=True)}">{id} · PDF {page} · {loc}</button>'
def n(id,ran):
 first=ran.split('–')[0].split('-')[0];citations.append((id,first,'novel'))
 return f'<button class="cite novel" data-source="{id}" data-page="{first}" data-range="{ran}">{id}-P{ran}</button>'
def table(headers,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def block(title,body,kind='inference'):
 labels={'inference':'本报告推断','proof':'正文论证','claim':'作者主张','limit':'证据边界'}
 return f'<div class="block {kind}"><span class="label">{labels[kind]}</span><h4>{title}</h4>{body}</div>'
def details(title,body,opened=False):return f'<details {"open" if opened else ""}><summary>{title}</summary><div class="detail-body">{body}</div></details>'
def steps(items):return '<ol class="steps">'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
def graph(nodes,edges,caption):
 # Draw a real directed network; retain a readable, fully labeled edge ledger below.
 labels=dict(nodes); pairs=[]; extra=0
 def endpoint(text):
  nonlocal extra
  if text in labels:return text
  for k,v in labels.items():
   if v==text:return k
  extra+=1;k='X'+str(extra);labels[k]=text;return k
 for e,(a,b,typ,label) in enumerate(edges,1):
  aa=a.split('、') if all(x in labels for x in a.split('、')) else [a]
  for aa1 in aa:pairs.append((endpoint(aa1),endpoint(b),typ,e))
 indeg={k:0 for k in labels};adj={k:[] for k in labels};levels={k:0 for k in labels}
 for a,b,typ,e in pairs:
  if a!=b:indeg[b]+=1;adj[a].append(b)
 queue=[k for k in labels if indeg[k]==0]
 for a in queue:
  for b in adj[a]:
   levels[b]=max(levels[b],levels[a]+1);indeg[b]-=1
   if indeg[b]==0:queue.append(b)
 cols={}
 for k in labels:cols.setdefault(levels[k],[]).append(k)
 maxcol=max(cols);rows=max(map(len,cols.values()));width=max(870,(maxcol+1)*240+35);height=rows*119+40
 coords={}
 for col,keys in cols.items():
  for j,k in enumerate(keys):coords[k]=(20+col*(width-235)/max(1,maxcol),20+(j+.5)*((height-40)/len(keys))-44)
 colors={'yes':'#176f69','need':'#a77a39','no':'#a2574c','compatible':'#657fa0'}
 svg=f'<svg class="network" viewBox="0 0 {width} {height}" role="img" aria-label="有向关系图，连线编号对应下方完整推理关系"><defs>'
 for typ,color in colors.items():svg+=f'<marker id="arrow-{len(chapters)}-{typ}" markerWidth="9" markerHeight="9" refX="8" refY="4" orient="auto-start-reverse"><path d="M0 0L9 4L0 8Z" fill="{color}"/></marker>'
 svg+='</defs>'
 for a,b,typ,e in pairs:
  ax,ay=coords[a];bx,by=coords[b];x1=ax+205;y1=ay+44;x2=bx-5;y2=by+44
  if x2<x1:x1=ax+102;y1=ay+88;x2=bx+102;y2=by-3;d=f'M{x1} {y1} C{x1} {y1+40} {x2} {y2-40} {x2} {y2}'
  else:d=f'M{x1} {y1} C{(x1+x2)/2} {y1} {(x1+x2)/2} {y2} {x2} {y2}'
  dash='stroke-dasharray="5,4"' if typ=="need" else ""
  start=f'marker-start="url(#arrow-{len(chapters)}-{typ})"' if typ=="compatible" else ""
  svg+=f'<path d="{d}" fill="none" stroke="{colors[typ]}" stroke-width="1.4" {dash} marker-end="url(#arrow-{len(chapters)}-{typ})" {start}/>'
  svg+=f'<text x="{(x1+x2)/2}" y="{(y1+y2)/2-6}" font-size="10" fill="{colors[typ]}" text-anchor="middle">{e}</text>'
 for k,text in labels.items():
  x,y=coords[k];svg+=f'<rect x="{x}" y="{y}" width="205" height="88" rx="4" fill="#f0f3eb" stroke="#bbcaba"/><text x="{x+12}" y="{y+18}" fill="#176f69" font-size="10" font-weight="600">{html.escape(k)}</text>'
  chunks=[text[i:i+16] for i in range(0,len(text),16)]
  for j,line in enumerate(chunks[:4]):svg+=f'<text x="{x+12}" y="{y+36+j*13}" fill="#263f46" font-size="10">{html.escape(line)}</text>'
 svg+='</svg>'
 ledger='<div class="graph-nodes">'+''.join(f'<div class="graph-node"><b>{key}</b>{text}</div>' for key,text in labels.items())+'</div><div class="edges">'+''.join(f'<div class="edge {typ}"><span>{i}. {a}</span><b>{"→" if typ=="yes" else "⇢" if typ=="need" else "↛" if typ=="no" else "↔"}</b><span>{b}</span><em>{label}</em></div>' for i,(a,b,typ,label) in enumerate(edges,1))+'</div>'
 return '<figure class="graph"><p class="graph-legend"><span>绿色 → 可保留</span><span>金色 ⇢ 需前提</span><span>红色 → 不成立</span><span>蓝色 ↔ 相容</span></p><div class="network-scroll">'+svg+'</div><figcaption>'+caption+' 连线编号对应展开后的完整关系；红线表示被审计并否定的推论，不能按普通箭头读取。</figcaption>'+details('展开节点释义与逐条推理关系',ledger)+'</figure>'
chapters=[]
def chapter(num,title,sub,conclusion,body):
 chapters.append({'num':num,'title':title,'sub':sub,'conclusion':conclusion,'body':body})
